            # 18 lvl очарование бессознательного, касанием, одно существо.
            # https://www.dandwiki.com/wiki/Arcane_Origin_(5e_Subclass)
            # 1 lvl 2 заклинания/кантрипа любого класса +1 заклинание на 4,9,14,20 lvl
            # 3 lvl +2 sorcery points; +2 SP на 6,12,18 lvl
            # 6 lvl эффект Color_Spray или Sleep как метамагия за 1 SP
            # 6 lvl мод.харизмы для кантрипов, для заклинаний за 1 SP
            # 6 lvl +1 талант метамагии
            # 14 lvl метамагия, одно заклинание без концентрации за 3 SP
            # 18 lvl сопротивление урону кроме force/psychic за 6 SP/минута
        # 30% -- выпускники инженерной академии Сталлионграда
            # https://www.dandwiki.com/wiki/Arithmetic_Soul_(5e_Subclass)
            # 1 lvl Интеллект вместо Харизмы для заклинаний (на выбор)
            # 1 lvl Универсальное уравнения, 1 после долгого отдыха
                # Заменить на кор.отдыхе за 1/2 sorcery_point/уровень
                # Уровень уравнения не больше уровня кастера.
                # 1) Arcane_Addition -- реакцией 1d4 к спасброску/навыку
                # 2) Arcane_Subtraction -- реакцией -1d4 от спаса/навыка
                # 3) Stable_Constant -- 12 вместо d20 к спасброску/навыку
                # 4) Probability_Collapse -- бросок 1d2 вместо спасброска
                # 5) Equivalent_Reprisal -- реакцией, обрасывание на 10 ft
                # 6) Derivative_Deduction -- True_Seeing на 60 футов, 1 раунд
                # 7) Numeric_Bane -- реакцией, помеха атаке/спасу/навыку
                # 8) Numeric_Boon -- реакцией, преимущество атаке/спасу/навыку
                # 9) Multiplicative_Force -- атака становится критической
                # 10) Vector_Acceleration -- заклинание линией толкает на 10 ft.
                # 11) Unstable_Variable -- реакцией, реролл атаки/спаса/навыка
                # 12) Power_Exponentiation -- +10 ft дальность, +1d8 урон/хиты
                # 13) Esoteric_Superaddition -- реакцией +2d4 к спасу/навыку
                # 14) Esoteric_Supersubtraction -- реакцией -2d4 к спасу/навыку
                # 15) Resonant_Nullification -- рассеивание магии 1 sorcery_point/круг
                # 16) Divide_By_Zero -- реакцией, 50 урона силовым полем всем на 120 ft
                # 17) Scaled_Norm -- минута действия, все d20 меньше 1/2 уровня мага = 12
                # 18) Transformation_Matrix -- создать слоты заклинаний 1 sorcery_point = 1 круг
                # 19) Unbound_Operator -- минута действия, все d20 становятся 4d6.
                # 20) Universal_Epiphany -- даёт 20 sorcery_point
            # 6 lvl Добавить 1d6 к Универсальному уравнению после отдыха.
            # 14 lvl Functional Metamagic
                # 1) Iterative_Spell -- перебросить атаку при промахе за 2 sorcery_point
