                # 3) Aries -- защита-без-брони 13 AC + DEX, сопротивляемость огню
                # 4) Capricorn -- навык insight, сопротивляемость грому
                # 5) Auriga -- +10 ft скорости, сопротивляемость молнии
                # 6) Corvus -- 60 ft Darkvision, сопротивляемость излучению
