#----
# Герои (ячейки заклинаний) (колдуны)
    # Колдуны, это проводники заклинаний своего покровителя. Стало быть Селестии.
    # Колдуны восстанавливают все ячейки заклинаний 1-5 круга на коротком отдыхе (2 передышки/день + сон)
    # lvl   | круг | ячеек/день | колдунов | заклн/год | бит/закл | доход/год | оборот/год
    # ----- | ---- | ---------- | -------- | --------- | -------- | --------- | ----------
    # 1-2   | 1    | 1.6 × 3    | 3800     | 5 500 000 | 1        | 1440 бит  | 5.50M бит
    # 3-4   | 2    | 2 × 3      |  950     | 1 710 600 | 1.5      | 2700      | 2.57
    # 5-6   | 3    | 2 × 3      |  240     |   432 000 | 2.2      | 3960      | 0.95
    # 7-8   | 4    | 2 × 3      |   60     |   108 000 | 7        | 12 600    | 0.76
    # 9-10  | 5    | 2 × 3      |   15     |    27 000 | 20       | 36 000    | 0.54
    # 11+   | 5    | 3 × 3      |    7     |    12 600 | 20       | 54 000    | 0.25
    # Колдуны 11+ lvl получают от покровителя арканумы 6-9 кругов, кои доступны только раз в сутки.
    # lvl   | круг | ячеек/день | колдунов | закл/год  | бит/закл | доход/год | оборот/год
    # ----- | ---- | ---------- | -------- | --------- | -------- | --------- | ----------
    # 11-12 | 6    | 1          |    4     |     1 500 | 60       |  18 000   | 0.072M бит
    # 13-14 | 7    | 1          |    2     |       900 | 130      |  39 000   | 0.078
    # 15-16 | 8    | 1          |    1     |       300 | 300      |  90 000   | 0.090
    # 17-20 | 9    | 1          |    1     |       300 | 600      | 180 000   | 0.180
    # Колдуны 9+ lvl в 2.4 раза чаще кастуют заклинания 4+ круга, чем волшебники.
    # Вернее Селестия кастует 0.6M/год, 1620/день, 68/час, 1.2/минуту.
    # Всего 7.8M заклинаний (из них 42.6k заклинания 5+ круга)
    # Оборот 11M бит (0.2% ВВП страны от 0.023% населения)
    #
    # Налоги с колдунов:
    # lvl   | доход/год  | уровень |  остаток | ставка/остат | налог + остаток  |  сумма   | колдн | Всего
    # ----- | ---------- | ------- | -------- | ------------ | ---------------- | -------- | ----- | -----
    # 1-2   | 1440       |  1 000  |     440  | 0.2 --> 0.3  |    200 + 132     |     332  | 3800  | 1.26
    # 3-4   | 2700       |  1 000  |   1 700  | 0.2 --> 0.3  |    200 + 510     |     710  |  950  | 0.68 
    # 5-6   | 3960       |  3 000  |     960  | 0.3 --> 0.4  |    800 + 384     |   1 184  |  240  | 0.28
    # 7-8   | 12 600     |  7 000  |   5 600  | 0.4 --> 0.6  |  2 400 + 3 360   |   5 760  |   60  | 0.35
    # 9-10  | 36 000     | 31 000  |   5 000  | 0.8 --> 0.9  | 20 000 + 4 500   |  24 500  |   15  | 0.37
    # 11-12 | 72 000     | 63 000  |   9 000  | 0.9 --> 1.0  | 50 000 + 9 000   |  59 000  |    4  | 0.24
    # 13-14 | 111 000    | 63 000  |  48 000  | 0.9 --> 1.0  | 50 000 + 48 000  |  98 000  |    2  | 0.20
    # 15-16 | 201 000    | 63 000  | 138 000  | 0.9 --> 1.0  | 50 000 + 138 000 | 188 000  |    1  | 0.19
    # Всего получается 3.6/11.0 млн. бит (33% доходов);
    # 5+ lvl колдуны платят 1.63/2.9 (56% доходов); 322 героев 5+ lvl (6.4%) владеют 26.4% всех доходов.
    # 7+ lvl колдуны платят 1.35/2.0 (68% доходов); 82 героев 7+ lvl (1.6%) владеют 18.2% всех доходов.

metadict_detail['-Герои-единороги (колдуны) (1 lvl)'] = {
        # В Эквестрии 5000 единорогов-колдунов, 2.3 на 10 000 населения (1/530 взрослых единорогов)
        # Колдуны восстанавливают свои заклинания на коротком отдыхе.
        # У них всего 1-4 ячейки заклинаний, зато наибольшего круга силы.
        # 90% -- выпускники медицинского университета
            # https://www.dandwiki.com/wiki/The_Thousand-Lives_(5e_Subclass)
            # 1 lvl мод.харизмы к проверкам Интеллекта (История)
            # 1 lvl заклинание другого класса, раз в день. Замена на долг.отдыхе.
                # дополнительное заклинание (но не слот) на 6,10,14 lvl
            # 1 lvl Расширенный список заклинаний
                # 1 круг Bane, Bless
                # 2 круг Augury, Enhance_Ability
                # 3 круг Bestow_Curse, Life_Transference
                # 4 круг Confusion, Death_Ward
                # 5 круг Legend_Lore, Reincarnate
            # 6 lvl 1d6 кость удачи после короткого/долгого отдыха
                # или восстановление ячейки, если выпало выше круга
            # 9 lvl уникальные воззвания
                # - Invocation_Borrowed_Arcana -- 2 заклинания любого класса
                # - Invocation_Barbarian_Memories 
                    # временные хиты после долгого отдыха = lvl кастера
                    # Reckless_Attack
                    # +1 мод.силы
                # - Invocation_Bardic_Memories
                    # удвоенный бонус мастерства для 2 навыков/инструментов
                    # один кантрип барда
                    # +1 мод.харизмы
                # - Invocation_Clerical_Memories
                    # иммунитет к болезням, отравлению, урону ядами
                    # Turn_Undead раз/сутки или за ячейку
                    # +1 мод.мудрости
                # - Invocation_Druidic_Memories
                    # Wild_Shape в зверя 1 CR раз/сутки (или за ячейку)
                    # +1 мод.мудрости
                # - Invocation_Fighting_Memories
                    # владение боевым оружием и щитами
                    # атака бонусным действием при касте/атаке
                    # +1 мод.силы/ловкости
                # - Invocation_Monastery_Memories
                    # 1d4 урона рукопашной атакой + мод.силы/ловкости
                    # рукопашная атака бонусным действием (число = мод.харизмы)
                    # +1 мод.силы/ловкости
                # - Invocation_Mystical_Memories
                    # one Psionic Focus of one Psionic Discipline of your choice.
                    # телепатия с существами более 2 Intelligence.
                    # +1 мод.интеллекта
                # - Invocation_Paladin_Memories
                    # владение боевым оружием и щитами, соматика заклинаний с оружием/щитом в руках.
                    # 45 хитов лечения, до 60 ft (восстановление за ячейку)
                    # +1 мод.харизмы
                # - Invocation_Ranger_Memories
                    # владение боевым оружием и щитами, соматика заклинаний с оружием/щитом в руках.
                    # Мудрость вместо Ловкости для броска инициативы
                    # +1 мод.мудрости
                # - Invocation_Roguish_Memories
                    # скрытая атака 1d6 урона
                    # уменьшение урона от атаки на 50% реакцией.
                    # +1 мод.ловкости
                # - Invocation_Sorcerous_Memories
                    # 3 sorcery_point, +1 SP за кор.отдыхе
                    # одна метамагия, замена на долгом отдыхе
                    # +1 мод.харизмы
                # - Invocation_Wizarding_Memories
                    # ритуалные заклинания
                    # один кантрип волшебника
                    # +1 мод.интеллекта
            # 10 lvl отмена урона, статуса, лечения. Реакцией, до 30 ft (число = мод.харизмы)
                # или повторный каст без траты ячейки, реакцией (проверка Харизмы vs 10+круг)
            # 14 lvl сопротивление одному типу урона
                # также иммунитет к очарованию
                # также защита от эффектов старения
                # бросок 1d20 при смерти, при 15+ реинкарнация через 24 часа.
            # https://www.dandwiki.com/wiki/The_Cosmic_Patron_(5e_Subclass)
            # https://www.dandwiki.com/wiki/The_Dictator_(5e_Subclass)
        # 10% -- сами-по-себе малефики
            # https://www.dandwiki.com/wiki/The_Imaginary_Friend_(5e_Subclass)
            # https://www.dandwiki.com/wiki/The_Dream_Dweller,_Variant_(5e_Subclass)
        '0 lvl (заговоры колдуна)':2,
        '1 lvl (заклинания колдуна)':1,
        '1 lvl (ритуальные заклинания колдуна)':1,
        '|?Волшебный предмет Common (кастер)':0.25,
        }

