# Герои (ячейки заклинаний) (друиды)
    # lvl    | круг | ячеек/день | магов  | закл/год   | бит/закл  | доход/год | оборот/год
    # ------ | ---- | ---------- | ------ | ---------- | --------- | --------- | ----------
    # 1-2+   | 1    | 2.75       | 20 400 | 19 900 000 | 1         | 825 бит   | 19.9M бит
    # 3-4+   | 2    | 2.75       | 5100   |  3 900 000 | 1.5       | 1238      | 5.85
    # 5-6+   | 3    | 2.75       | 1275   |    970 000 | 2.2       | 1815      | 2.13
    # 7-8+   | 4    | 1.75       | 319    |    180 000 | 7         | 3675      | 1.26
    # 9-10+  | 5    | 1.5        | 80     |     48 000 | 20        | 9000      | 0.96
    # 11-12+ | 6    | 1.1        | 36     |     12 000 | 60        | 19 800    | 0.72
    # 13-14+ | 7    | 1          | 16     |      5 800 | 130       | 39 000    | 0.75
    # 15-16+ | 8    | 1          | 6      |      2 600 | 300       | 90 000    | 0.78
    # 17-20  | 9    | 1          | 2      |      1 100 | 600       | 180 000   | 0.66
    # Всего 25.0M заклинаний/год (из них 70k заклинания 5+ круга)
    # Оборот 33M бит (0.55% ВВП от 0.093% населения, ×5.9 богатство)
    #
    # Налоги с чародеев (доходы с кругов суммируются, кантрипы и ритуалы не учитываем):
    # lvl   | доход/год  | уровень |  остаток | ставка/остаток | налог + остаток  |  сумма  | магов | Всего
    # ----- | ---------- | ------- | -------- | -------------- | ---------------- | ------- | ----- | -----
    # 1-2   | 825        |      0  |     165  | 0.2            |      0 + 165     |     165 | 15300 | 2.53
    # 3-4   | 2100       |  1 000  |   1 100  | 0.2 --> 0.3    |    200 + 330     |     530 | 3800  | 2.01 
    # 5-6   | 3900       |  3 000  |     900  | 0.3 --> 0.4    |    800 + 360     |   1 160 |  960  | 1.11
    # 7-8   | 7600       |  7 000  |     600  | 0.4 --> 0.6    |  2 400 + 360     |   2 760 |  239  | 0.66
    # 9-10  | 17 000     | 15 000  |   2 000  | 0.6 --> 0.8    |  7 200 + 1 600   |   8 800 |   60  | 0.53
    # 11-12 | 36 000     | 31 000  |   5 000  | 0.8 --> 0.9    | 20 000 + 4 500   |  24 500 |   20  | 0.49
    # 13-14 | 75 000     | 63 000  |  12 000  | 0.9 --> 1.0    | 50 000 + 12 000  |  62 000 |   10  | 0.62
    # 15-16 | 165 000    | 63 000  | 102 000  | 0.9 --> 1.0    | 50 000 + 102 000 | 152 000 |    4  | 0.61
    # 17-20 | 345 000    | 63 000  | 282 000  | 0.9 --> 1.0    | 50 000 + 282 000 | 332 000 |    2  | 0.66
    # Всего получается 9.2/33 млн. бит (28% доходов);
    # 5+ lvl друидов платят 4.7/7.3 (64% доходов); 1295 героев 5+ lvl (6.3%) владеют 22% всех доходов.
    # 7+ lvl друидов платят 3.6/5.1 (71% доходов); 335 героев 7+ lvl (1.6%) владеют 16% всех доходов.

