# Заклинания (доступные)
    # - !!! — изменённые заклинания.
    # - +++ — готовы в коде dnd-mass-combat-simulation
    # - @@@ — собственные заклинания, Homebrew
    # Notation [School | Defense | Damage_Type] (R) (C)
    # School -- школа магии:
        # Illusion [Ilu] -- иллюзии
        # Divination [Div] -- прорицание
        # Transmutation [Tra] -- преобразование
        # Enchantment [Enc] -- очарование
        # Necromancy [Nec] -- некромантия
        # Abjuration [Abj] -- ограждение
        # Evocation [Evo] -- воплощение
        # Conjuration [Cnj] -- вызов
    # Defense -- спасбросок, защита
        # Strength [Str] -- сила
        # Dexterity [Dex] -- ловкость
        # Constitution [Con] -- телосложение
        # Intelligence [Int] -- интеллект
        # Wisdom [Wis] -- мудрость
        # Charisma [Chr] -- харизма
        # Armor_Class [AC] -- класс доспеха, КД
        # Hitpoints [hp] -- число хитов
    # Damage_Type -- тип урона
        # Оружие:
        # - piercing -- колющий
        # - bludgeoning -- дробящий
        # - slashing -- рубящий
        # Стихийные:
        # - acid -- кислота
        # - cold -- холод
        # - fire -- огонь
        # - thunder -- звук
        # - lightning -- электричество
        # Магия:
        # - force -- силовое поле
        # - psychic -- психический
        # - radiance -- излучение
        # - necrotic -- негативная энергия
        # - healing -- позитивная энергия
        # Прочие:
        # - poison -- яд
    # (R) -- ритуал, 10 минут каста без затраты слотов.
    # (C) -- кантрип, заговор, не тратящее слот заклинание.
    # (C) -- концентрация на заклинании.

