        # Мощность Shape_Water: (5ft)^3 × 1000kgf/m³ × 5ft/6s = 8.8kW
        # Теплоёмкость воды -- 4.2 кДж/(кг·K), кристаллизация -- 330 кДж/кг
        # Заморозка воды (20°C --> 0°C --> лёд): 4.2kJ × 20 + 330kJ = 414 кДж/кг
        # Заморозка: (5ft)^3 × 1000kg/m³ × (4.2kJ/kg × 20 + 330kJ/kg)) / 8.8kW = 46 часов
        # Полная заморозка 3.5t воды при 20°C = 46 часов работы Shape_Water и 1.5 ГДж.
