metadict_detail['_++0 lvl (C) Шквал (0 lvl Gust)'] = {
        # * "Шквал" (Gust) [Evo|Str|-] — 30 футов, действием, отталкивает на 5 футов, спасбросок силы. Страшнее, чем кажется. Можно сбрасывать лучников с городских стен, вышвыривать солдат за борт в абордажном бою, или наполнять паруса ветром. Мощность последнего при скорости потока в 35 м/с будет 3.2 киловатта (что сравнимо с работой 32 гребцов). Если принять Шквал за реактивную струю с 75% КПД, этих 3.2 кВт хватило бы, чтобы поднять в небо 68 кг пегаса с аэродинамическим качеством ≥10, но в описании заклинания мощность такого применения ограничена 5 lbf × 10 ft = 68 Ватт, чего не хватило бы даже альбатросу, зато в точности равняется мощности Mage_Hand.
        # Физика заклинания:
        # Формула ветрового давления:
            # Р = 1/2 p × V ^ 2 × k
            # Гда:
            # P -- давление (кгс/м²)
            # p -- плотность воздуха (1.2 кг/м³ при 20°C)
            # V -- скорость (метров/секунду)
            # k -- коэффициент парусности (0.5 здание, 0.8 парус барка)
        # Ветровое давление на человека:
            # V = 10 м/с Р = 3 кгс/м² (свежий ветер)
            # V = 30 м/с Р = 27 кгс/м² (устоять несложно)
            # V = 40 м/с Р = 48 кгс/м² (устоять возможно)
            # V = 50 м/с Р = 75 кгс/м² (устоять невозможно)
            # V = 60 м/с Р = 110 кгс/м² (унесёт как листок)
            # Ветер >33 м/с, это ураган по шкале Бофорта
            # https://ru.m.wikipedia.org/wiki/Шкала_Бофорта
        # Реальные примеры:
            # V = 50 м/с P = 75 кгс/м² (Парашютист 80 кг в группировке S = 0.5m²)
            # V = 35 м/с P = 60 кгс/м² (Парашютист парит раскрытым S = 1.0m²)
        # Работа заклинания:
            # Мощность: cylinder(2.5ft,30ft) × 1.2kgf/m³ × 35m/s = 6.9kW
            # Импульс: cylinder(2.5ft,30ft) × 1.2kg/m³ × 35m/s / 5ft/s = 460kg
            # Отталкивает до 460 килограмм на 5 футов за секунду.
        #'-Мощность механическая, заклинания (киловатт-час)':7.3 / 600,
        }

metadict_detail['_++0 lvl (C) Авиатор (0 lvl Aviator)'] = {
        # * @@@ "Авиатор" (Aviator) [Evo|Con|thunder] (C) — 1lb маффинов, на себя, действием, час концентрации. Создаёт два 5-футовых крыла из уплотнённого воздуха, даёт скорость планирования 300 футов со снижением на 30 футов/раунд, при этом снижает урон от падения или столкновения на 1d10. Ценой потери концентрации можно вызвать один из следующих эффектов: 1) Преграда: реакцией снижает урон на 1d10 от одной атаки дальнобойным оружием. 2) Импульс: Реакцией либо бонусным действием даёт кастеру 15 футов хода прыжком. 3) Выброс: Реакцией либо бонусным действием струя линией на 10 футов, 1d10 урона громом, спасбросок Телосложения полный, при этом импульс отталкивает кастера на 15 футов в противоположенную сторону. На больших уровнях усиливается: на 5 lvl -- кость 2d10, импульс 30 футов; на 11 lvl -- кость 3d10, импульс 60 футов; на 17 lvl -- кость 4d10, скорость полёта 60 футов.
        # Физика заклинания:
            # Лётный щит с запасам сжатого воздуха вокруг крыльев пегаса.
            # Перья пегаса, суть миниатюрные компрессоры с соплом Лаваля.
            # Они сжимают воздух за счёт содержащихся в нём частиц магии.
            # Мембрана щита со сжатым воздухом удлиняет крылья до 5 футов.
            # Сжатый воздух компенсирует 68kg × 4.6m/s импульса (15ft падения)
            # Плотность воздуха -- 1.2 кг/м³ Теплоёмкость -- 1.006 кДж/(кг·К)
            # В щите хранится 0.7 кг воздуха, сжатого до 2 атмосфер (0.3m³)
        # Воздух нагревается 6 секунд с мощностью в 30 кВт (крылосила):
            # Уравнение: T = E / (C × m)
            # Где:
            # T — Температура (в кельвинах)
            # E — Энергия в килоджоулях (30kW×6s = 180kJ)
            # C — удельная теплоёмкость (1.006kJ/(kg·K))
            # m — масса в килограммах (0.7 кг)
            # Подстановка:
            # (30kW × 6s) / (1.006kJ/(kg·K) × 0.7kg) = 256 кельвинов
        # Зная температуру можно вычислить давление:
            # Уравнение состояния идеального газа: p × Vm = R × T
            # Где:
            # p — давление (в Паскалях)
            # Vm — молярный объём (22.41 л/моль)
            # R — Универсальная газовая постоянная (8314.5 Дж/(моль·К)
            # T — Абсолютная температура, в кельвинах (293K + 256K)
            # Уравнение: p = (R × T) / Vm
            # Подстановка:
            # (GasConstant × (293K+256K)) / 22.41l/mol = 204kPa (2 атмосферы)
        # Скорость реактивной струи зависит от давления и температуры:
            # V=sqrt((T×R/M) × (2×k/(k-1)) × [1-(Pe/p)^((k-1)/k)])
            # Где:
            # V — Скорость газа на выходе из сопла, м/с
            # T — Абсолютная температура газа на входе (293+256=549K).
            # R — Универсальная газовая постоянная (8314.5 Дж/(моль·К)
            # M — Молярная масса газа, кг/киломоль (для воздуха 29 кг/киломоль)
            # k — Показатель адиабаты (для сухого воздуха при 20°C — 1.4)
            # Pe — Давление газа на выходе из сопла (атмосфера)
            # P — Давление газа на входе в сопло (2 атмосферы)
            # Подстановка (в qalculate):
            # sqrt((549K×GasConstant / 29kg/kmol) × (2×1.4/(1.4-1)) × [1-(atmosphere/2atmosphere)^((1.4-1)/1.4)])
        # Отражение снарядов импульсом сжатого воздуха:
            # V = 445 м/с (скорость звука 340 м/с)
            # Выброс: 0.7 kgf × 445m/s = 3.1 кВт (78J за 1/40s)
            # Импульс: 0.7 kg × 445m/s / 68kg = 4.6 м/с (15 ft/s)
            # Лонгбоу 70g, 150J, 200ft/s vs Выброс, 18g, 78J, 5ft.
            # Пробой щита стрелой вызывает выброс сжатого воздуха.
        # Урон реактивной струи (5×10ft линия):
            # Контузия: 150-160 dB (0.6-2 kPa)
            # Плотность энергии: 3.1kJ / cone(2.5ft,10ft) = 1.7kPa
            # Выброс ошеломляет врага. Импульс отталкивает пегаса.
        # Падение ("Книга игрока" DnD 5e, стр 183):
            # sec | m/s  | ft  | ft/r | урон | dmg | Скорость отброса
            # --- | ---- | --- | ---- | ---- | --- | ----------------
            # 1/3 | 3.3  | 10  | 60   | 1d6  | 4   | Безопасно бойцу
            # 2/3 | 6.5  | 20  | 120  | 2d6  | 7   | Порог поражения
            # 1   | 9.8  | 30  | 180  | 3d6  | 11  | -
            # 2   | 19.6 | 100 | 400  | 10d6 | 35  | >50% потерь
            # 3   | 29.4 | 260 | 600  | 20d6 | 70  | 100% потерь
            # 9.8m/s² × (1/3) second to ft/round = 64 ft/round скорость
            # (9.8m × (3^2-1)) / (2-1) to ft = 257 ft падения за 3 секунды.
            # Максимум урона падения в DnD 5e, это 20d6 за 200 футов.
            # Максимум скорости падения, это 30 м/с, 600 ft/round.
        # Масса щита -- 3/4 lb
            # Плотность щита (Graphitic carbon nitride) — 2.336 g/cm³
            # Масса щита: 0.3m³ / 0.2m × 0.1mm × 2.336 g/cm³ = 350 грамм
            # Для синтеза щита при 40% КПД достаточно съесть 1lb маффинов.
            # 1lb × 433kcal/100g / 1 hour × 40% = 0.9 кВт
        }

metadict_detail['_++0 lvl (C) Сопротивление (0 lvl Resistance)'] = {
        # * !!! "Сопротивление" (Resistance) [Abj|-|-] (C) — 4oz маффин, касание, бонусным действием, минута концентрации. Два типа защиты на выбор кастера: 1) Даёт +1d4 к выбранному спасброску; 2) Поглощает 1d4 урона выбранного типа раз в ход каждого врага. Суперская защита для бойца первого ряда с Feat_Heavy_Armor_Master (который получает в среднем 5.5hp поглощения урона, когда у регуляров средний урон 5.7/атака). На больших уровнях усиливается: на 5 lvl -- 5hp защиты, либо 1d8 к спасброску; на 11 lvl -- 10hp защиты, либо 1d10 к спасброску; на 17 lvl -- 15hp защиты, либо 1d12 к спасброску.
        # Физика заклинания:
        # Состав мембраны:
            # Нитрид углерода (C3N4) -- 39% углерода, 61% азота
            # Плотность нитрида углерода (Graphitic carbon nitride) — 2.336 g/cm³
            # - Энергия разрыва простой углерод-углеродной связи (C2) — 29.4 МДж/кг
            # - Энергия диссоциации атмосферного азота (N2) — 33.63 МДж/кг
            # - Энергия на килограмм щита — 31.7 МДж/кг (1.1 кг угля)
            # Рост пони 0.7 метра (в холке), площадь тела 1.6 м²
            # 5 сантиметров амортизации: 1.6m² × ((0.75m / 0.7m) ^ 2) = 1.84 м²
            # 0.01 миллиметра мембраны: 1.84m² × 0.01mm × 2.336g/cm³ = 43 грамма
            # Энергия на синтез мембраны -- 1.4 МДж (один 100-граммовый маффин)
        # https://www.dndbeyond.com/spells/2618947-resistance
        # https://te4.org/wiki/Energy_decomposition_(talent)
        '_++0 lvl (C) Сопротивление (0 lvl Resistance) (%)':[
            '(value / x) * 100',
            '0 lvl Сопротивление (0 lvl Resistance) (требуется)',
            ],
        }

