metadict_detail['_++1 lvl (S) Земляной кабанчик (1 lvl Earthen_Servant)'] = {
        # * @@@ "Земляной кабанчик" (Earthen_Servant) [Cnj|-|-] — 1 бит (30lb угощений, ест за шестерых), 30 футов, действием, час концентрации. Призывает земляного кабанчика, маленького земляного элементаля с CR 1/4 (16hp, 13AC, +4 мод_атаки, 1d4+2 урона, 15ft скорости копания). За час он может вспахать 5ft × 15ft/round to ha/hour = 0.42 гектара (1 акр). Один кабанчик с его мощностью земляных работ в 17.5 кВт заменяет 3 часа Mold_Earth, но готовка 30lb домашних угощений потребует 2-6 нормо-часов, или короткий отдых + 10lb рационов + проверка Мудрости (инструменты повара) против СЛ 15. Невкусно накормленный кабанчик обижается и склонен красть припасы, пока все спят.
        # Физика заклинания:
        # Earthen_Servant: 0.42 ha/day × 200 day = 84 га/год, 12.6 ГДж 200 бит.
        # Трактор (1927 год) 15hp, 100 га/год, 500 часов/год -- 201/3000 МДж/га.
        # За 6 часов работы 4 лошади пашут на 65MJ кинетики, тратят 360MJ пищи.
        # За час кабанчик пашет на 63MJ, съедает 75MJ (1/50 годового рациона)
        # Применение:
        # - хороший разведчик, подземный же.
        # - идеальный миноукладчик, сапёр, шахид.
        # - идеальный трубопрокладчик или кабелеукладчик.
        # - может служить грейдером, скрепером, бульдозером.
        # - может помогать в ремонте балластного слоя железных дорог.
        # - может очищать каналы, углублять реки (дыхание ему не нужно.
        # - может работать в шахтах, карьерах, но не лучше Mold_Earth.
        # - может сортировать глину на производстве кирпича, керамики.
        #
        # Пд Эквестрия живёт популяция в >80k земляных элементалей:
        # _++1 lvl (S) Земляной кабанчик (1 lvl Earthen_Servant) | 15,876,322
        # _++1 lvl (S) Земляной кабанчик (кастов/день).......... | 79,382
        # _++1 lvl (S) Земляной кабанчик (кастов/кантон-день)... | 57
        # _++1 lvl (S) Земляной кабанчик (гектаров/кантон-день). | 24
        # amber Понивильский кантон -E '|---'
        # _++1 lvl (S) Земляной кабанчик (гектаров/кантон-год).. | 4,800
        # _++1 lvl (S) Земляной кабанчик (рационов/кантон-год).. | 229
        # |----Обрабатываемые земли (гектар)...................... | 6,757
        # |---Пашня (гектар)...................................... | 5,414
        # |---Сады (гектар)....................................... | 943
        # |---Огороды (гектар).................................... | 449
        # |---Плантации (гектар).................................. | 210
        # 16M бит, это 0.27% ВВП Эквестрии. Замена тракторов.
        # https://www.dandwiki.com/wiki/Earthen_Servant_(5e_Spell)
        # https://www.dandwiki.com/wiki/Earthen_Servant_(5e_Creature)
        }

metadict_detail['_++1 lvl (S) Оживить деревяшку (1 lvl Animate_Wood)'] = {
        # * @@@ "Оживить деревяшку" (Animate_Wood) [Tra|-|-] — 1 бит (редкие масла), касание, действием, 24 часа действия. Маленький деревянный предмет оживает, отращивает рожки и ножки с копытцами. Может переносить вещи до 10lb, может заботиться о саде и огороде подобно Unseen_Servant, но без постоянного контроля. Пуглив, от опасности убегает, что и делает в конце срока своей службы, превращаясь в росток в лесу. На больших уровнях срок службы увеличивается до 1 неделя/круг. С 6 круга служит пока не отпустят, тихонько надеясь получить Пробуждённый разум.
        # Деревяшки окупаются, за сутки наработает на 2-5 бит.
        # _-Валка среднего леса (дерево)..................... | 100,350,883
        # _++1 lvl (S) Оживить деревяшку (1 lvl Animate_Wood) | 2,480,452
        # _++1 lvl (S) Оживить деревяшку (кастов/день)....... | 8,268
        # 1/40 срубленных деревьев оживает на новом месте.
        }

