metadict_detail['_++1 lvl (S) Добряника (1 lvl Goodberry)'] = {
        # * !!! +++ "Чудо-ягоды" (1 lvl Goodberry) [Cnj|-|-] — касание, действием, 24 часа действия. Создаёт 10 ягод, каждая ягода восстанавливает 1 hp и насыщает на сутки. При этом не даёт достаточно энергии, а только избавляет от чувства голода и вызванного голодом истощения. Чтобы полностью насытиться нужно 10-20 ягод.
        # Физика заклинания:
        # Калорийность ягоды -- 220 килокалорий (40 грамм, 0.1 lb).
        # В 40-граммовой ягоде (берём состав арахиса):
            # Белки -- 10.5 грамм (1.06 МДж)
            # Жиры -- 18.1 грамм (2.14 МДж), 
            # Углеводы -- 4.0 грамм (0.4 МДж)
            # Вода и прочие вещества -- 7.4 грамма (18% влажности, плотная такая ягода)
        # Необходимо 3.6 МДж (энергия 1/10 литра бензина)
        # Диссоциация ингредиентов (воздух и вода):
            # Энергия химических связей грамма углеводов/белков -- 4.1 килокалории (17.2 кДж).
            # Энергия химических связей грамма жиров (триглицеринов) -- 9.3 килокалорий (38.9 кДж).
            # ----
            # Энергия диссоциации углекислого газа — 1506 кДж/моль
            # Молярная масса углекислого газа — 16*2+12=44 г/моль
            # На каждый грамм углерода понадобится 126.5 кДж энергии, при 100% КПД реакции.
            # ----
            # Энергия диссоциации азота — 941.64 кДж/моль
            # Молярная масса азота — 14*2=28 г/моль
            # Энергия диссоциации воды — 285 кДж/моль
            # ----
            # На грамм азота потребуется 33.63 кДж энергии.
            # Молярная масса воды — 16+2=18 г/моль
            # На каждый грамм водород-кислородной смеси (гремучего газа), понадобится 15.83 кДж энергии.
            # ----
            # Синтез грамма белка потребует 101.161 кДж энергии, при близком к 100% КПД процесса.
            # Грам жиров (элементарный состав схожий, энергия триглициринов вдвое больше) -- 118 кДж
            # ----
            # Для синтеза грамма глюкозы растения тратят от 1 до 15.8 МДж энергии (КПД 0.64-10%)
            # Заклинание срабатывает за 6 секунд и не сжигает добрянику, так что КПД близок к 100%
        # Заклинание создаёт 10 ягод (0.4 кг), что требует 36 МДж энергии.
        # Заклинание должно занимать хотя бы 1 час (поток 10 кВт, 1 кВт/ягоду).
        '_++1 lvl (S) Добряника (1 lvl Goodberry) (%)':[
            '(value / x) * 100',
            '1 lvl Добряника (1 lvl Goodberry) (требуется)',
            ],
        }

