metadict_detail['_++2 lvl (R) Поиск животных или растений (2 lvl Locate_Animals_or_Plants)'] = {
        # * !!! "Поиск животных или растений" (Locate_Animals_or_Plants) [Div|-|-] (R) — на себя, действием, ритуал, 5 миль радиус. Направление и расстояние до ближайшего существа выбранного вида. Не находит людей, но запросто найдёт коня, корабельную крысу, постельную блоху, зерно пшеницы. Это верный способ обнаружить людей в дикой местности. Homebrew: ищет существ не меньше маленького размера, не менее 10 lb (5 килограмм). Всё равно найдёт собаку, но хотя бы не блох и корабельных крыс. Чтобы спрятать свою живность используйте Nystuls_Magic_Aura.
        }

metadict_detail['_++2 lvl (S) Поиск предмета (2 lvl Locate_Object)'] = {
        # * "Поиск предмета" (Locate_Object) [Div|-|-] — на себя, действием, 1000-футовый радиус, 10 минут концентрации. Можно искать известный предмет, или вид предметов: одежду, монеты, оружие. Если объект движется, показывает направление движения. Заклинание не действует, если предмет закрыт тонким свинцовым листом. Заклинание не блокируется ни деревом, ни грунтом, ни скалой. Позволяет обнаружить засады: всего-то идём в 1000 футах от своих и ищем порох. Позволяет находить сокровища на древних капищах, где всё уже давно заросло и покрылось землёй.
        }

