metadict_detail['_++2 lvl (S) Бесследное передвижение (2 lvl Pass_Without_Trace)'] = {
        # * "Бесследное передвижение" (Pass_Without_Trace) [Abj|-|-] (C) — на себя, действием, 30-футовый радиус, час концентрации. Даёт бойцам вокруг кастера +10 к проверкам Ловкости (Скрытность), их нельзя выследить без помощи магии, они не оставляют следов. Это единственный надёжный способ провести сотню пыхтящих и громыхающих солдат перед носом у вражеской армии. Бонус просто огромен, а радиус в 30 футов позволяет надёжно скрыть любой отряд. Монахи выбравшие "Путь тени" исполняют это заклинание ценой 2 Ки, то есть могут повторять его после каждого короткого отдыха (по правилам "сурового реализма" это раз в сутки). В мире 50 000 монахов 3+ lvl, из них около 5000 знающих "Бесследное передвижение" за счёт "Техники тени", есть неслабый шанс таких повстречать.
        }

metadict_detail['_++2 lvl (S) Вечный огонь (2 lvl Continual_Flame)'] = {
        # TODO: недостаёт 80% корундовой пыли на Continual_Flame (13.5/72 млн бит, 0.6/3.7 млрд бит)
            # При этом Эквестрия импортирует 9.3M карат пыли, производит 4.2M карат (1 карат = 1 бит)
            # Вся доступная драгоценная пыль:
            # - 4.5/6M карат алмазы (Алмазные псы)
            # - 9/12M карат сапфиры (Кирины)
            # - 4.2/5.6M карат рубинов (Эквестрия)
            # - 16.5/22M карат изумрудов (Зебры)
            # Всего 34.2/72M карат
        # * "Вечный огонь" (Continual_Flame) [Evo|-|-] — 50 бит (Common драгоценный камень), касание, действием, пока не рассеется. Пламя эквивалентно яркости факела (20 футов яркого света, 20 футов тусклого). Реалистичная оценка светимости такая: сила света факела из ветвей можжевельника и сосновой смолы равна 14 кандел (176 люмен, подобно 20-ваттной лампе накаливания).
        # Предметы с Continual_Flame, это универсальное средство обмена наравне с золотом. Они вечные, полезные, портативные, сложные в добыче/изготовлении. Пони называют их яркосветами. Лампа в доме, это большое вложение, зато она на поколения становится капиталом семьи. При мощности в 3 ватт и среднем сроке службы в 50 лет это 5 ГДж энергии.
        # Физика заклинания:
        # Для сравнения: 
            # - 102+86 бит на 425 ГДж дров при 20% КПД от ТЭС до 50-ваттной угольной лампочки (432 штуки)
            # - 6+36 бит на 25 ГДж топлива при 20% КПД от ТЭС до 3-ваттной натриевой лампочки (72 штуки)
            # * энергия в ценах Эквестрии
        # Капиталы в Continual_Flame:
            # Сумма капиталов:
                # Всего 62 млн светокристаллов, 3.7 млрд бит (10% капиталов Эквестрии)
                # При сроке службы в 50 лет 74 млн бит/год компоненты (1.2% ВВП Эквестрии)
                # 1 Continual_Flame = 1 тонна ржаной муки, патефон, фотоаппарат, два пальто.
                # 1 Continual_Flame = 1.5 месячные зарплаты бедных пони (50% населения).
                # -|$ Продукция, стоимость (бит)................................... | 3,301,552,194
                # |Утварь стеклянная (лампа светокристальная 10x10x20-см, 200 Лм).. | 20,171,972
                # |Утварь стеклянная (люстра светокристальная 30x30x20-см, 600 Лм). | 7,574,379
                # |Утварь стеклянная (люстра светокристальная 40x40x20-см, 1200 Лм) | 3,108,690
                # amber Эквестрия -E светокристальная
            # Доходы эквестрийских семей и светокристальные лампы в домах:
                # Норма сбережений -- 15% (40+ лет на накопление ×6 дохода)
                # Уровень деволюции наследства -- 3-3.5% (наследование в 30 лет)
                # Доходность капитала: 6% рента - 4% налоги = 2% (720 млн, 12% ВВП)
                # Страта    | Семей | Доля | Капитал | Капитал/семью | Рента/семью
                # --------- | ----- | ---- | ------- | ------------- | -----------
                # Кабаны    | 44k   | 1%   | 20%     | 164 000 бит   | 3275
                # Богатеи   | 0.4M  | 9    | 30      | 25 000        | 490
                # Середняки | 1.8M  | 40   | 40      | 8200          | 165
                # Бедняки   | 2.2M  | 50   | 10      | 1636          | 33
                # - Семья богатеев (2000 бит/год) -- 207 светокристаллов, 12 420 бит (x6.5 середняков)
                # - Семья середняков (990 бит/год) -- 32 светокристаллов, 1 920 бит (x4 бедняков)
                # - Семья бедняков (500 бит/год) -- 8 светокристаллов, 480 бит (x4 селян)
                # - Семья селян (500 бит/год) -- 2 светокристаллов, 120 бит
        # Сравнение источников света:
            # Светоотдача:
                # Тип светильника    | кандел | люмен/ватт
                # ------------------ | ------ | ----------
                # Стеариновая свеча  | 1      | 0.3
                # На угольном газе   | 5-10   | 1-2
                # Вольфрамовая нить  | 60     | 5-15
                # Люмисцентная лампа | 500    | 100
                # Натривая лампа     | 1000   | 200
                # 1 кг воска = 176 часов горения (Grain into Gold стр 44)
            # Нормы освещённости:
                # Тип помещения/условий            | Норма освещенности
                # -------------------------------- | ------------------
                # Полдень, прямой свет Солнца      | 32-130k люкс
                # Полдень в декабре-январе         | 4000 люкс
                # Восход и закат в ясный день      | 400
                # Обычный офис                     | 300
                # Рабочий кабинет                  | 300
                # Зал для конференций              | 200
                # Детская комната                  | 200
                # Жилая комната, кухня             | 150
                # Холл, коридор                    | 75
                # Ванная комната, душевая, санузел | 50
                # Уличное освещение                | 1-10
                # Цветовой порог человека          | 3
                # Полнолуние при ясном небе        | 0.3
                # Молодой месяц (четверть луны)    | 0.01
                # Звёзды, безлунная ночь           | 0.001
                # Тёмная облачная ночь             | 0.0001
                # 1 люкс = 1 люмен/кв.метр
                # https://ru.m.wikipedia.org/wiki/Люкс
            # Электрические лампы начала 20 века:
                # Лампы накаливания, 1600-1700°C, 2-2.5 ватт/свечу.
                # Больше температура, меньше срок службы, лучше свечение:
                # ватт/люмен | люмен/лампа  | 50% потеря свечения | долговечность
                # ---------- | ------------ | ------------------- | -------------
                # 0.14       | 263          | 110 часов           | 270 часов
                # 0.22       | 209          | 325                 | 390
                # 0.26       | 202          | 1050                | 1050
                # 1 candlepower equals 12.57 lumens
                # https://ru.wikisource.org/wiki/ЭСБЕ/Электрическое_освещение
                # https://ru.wikisource.org/wiki/ЭСБЕ/Освещение_калильное
                # https://ru.wikisource.org/wiki/ЭСБЕ/Освещение
                # https://ru.m.wikipedia.org/wiki/Свеча_Хефнера
                # https://en.m.wikipedia.org/wiki/Candlepower
                # https://ru.m.wikipedia.org/wiki/Кандела
            # Факел
                # 1 факел = 14 кандел = 176 люмен
                # 1 факел = 20-ваттная лампа накаливания
                # Мощность горения факела (0.45 кг, 50% сгорание) -- 920 ватт
                # Чем выше температура горения факела, тем больше доля видимого света.
                # Ветки можжевельника, связанные плющом, сосновая смола, 61 минута горения, 633°C
                # Средняя освещённость на дистанции 40 см -- 22 люкса (44 люмен?)
                # Радиус света (до темноты менее 1 люкс) -- 2.5 метра (сфера 78.5 кв.метров)
            # Факел (правила DnD 5e)
                # Площадь сферы: S = 4 * Pi * r ^ 2
                # Яркий свет на 10 футов (2.8 метра, 98 м²) -- 1.8 люкса
                # Тусклый свет на 20 футов (7 метров, 615 м²) -- 0.3 люкса (полнолуние при ясном небе)
                # https://www.dandwiki.com/wiki/5e_SRD:Torch
            # Свеча
                # 1 свеча = 1 кандела = 12.6 люмен
                # Мощность горения стеариновой свечи -- 50 ватт
                # Площадь сферы: 4 * 3.14 * 0.4^2 = 2 кв.метра
                # На расстоянии 40 см -- 6.3 люкс.
                # https://ru.m.wikipedia.org/wiki/Люкс
                # https://ru.m.wikipedia.org/wiki/Люмен
                # https://ru.m.wikipedia.org/wiki/Кандела
            # Масляная лампа
                # 1 лампа = 0.6 кандел = 7.5 люмен
                # Мощность горения топлёного сала (37 МДж/кг, 3.3 МДж в плошке, два часа) -- 460 ватт
                # Плошка 150 миллилитров, животный жир, более часа горения, 176°C
                # Средняя освещённость на дистанции 40 см -- 3.71 люкса
                # https://www.townsends.us/collections/food-drink/products/redware-grease-lamp-lantern-p4142-p-864
            # Очаг
                # 1 маленький очаг = 3.1 кандел = 39 люмен
                # Ветки можжевельника и дуба. Диаметр костра -- 23 см. Высота пламени -- 40 см.
                # Площадь этого очага в 12 раз меньше, чем у Create_Bonfire, мощность 1 кВт.
                # Средняя освещённость на дистанции 40 см -- 19.2 люкса
        # Световой поток -- 200 люмен; мощность -- 3 ватта (люминесцентная лампа)
        '_++2 lvl (S) Вечный огонь (2 lvl Continual_Flame) (%)':[
            '(value / x) * 100',
            '2 lvl Вечный огонь (2 lvl Continual_Flame) (требуется)',
            ],
        }

