metadict_detail['_++3 lvl (S) Полёт (3 lvl Fly)'] = {
        # * +++ !!! "Полёт" (Fly) [Tra|-|-] (C) — касание, действием, 10 минут концентрации. Цель получает 60 футов скорости полёта. Цель падает, когда заклинание заканчивается. Мощность этого заклинания (для 136 кг бойца): 300lbf × 60ft/6s = 4.1 кВт. Меня всегда смущала скорость. 60 футов, это 3 метра/секунду, или 10.8 км/час. На простейшем крылатом костюме (Wingsuit) можно легко достичь скорости в 70+ км/час в свободном планировании. Homebrew: с помощью этого заклинания можно подняться до 6000 футов (миля высоты), а затем планировать со скоростью 300 футов и снижением на 30 футов/раунд, если изготовите планёр, что даст +20 минут полёта и 10 миль дистанции. С высоты в 6000 футов в солнечный день в океане видно на 90 миль (угловой размер корабля на такой дистанции 0.2-0.9 минут, различим только в подзорную трубу).
        # Физика заклинания:
            # Индукция 1 Тесла, 1.5m магнитное кольцо, 60ft высота, 150lb пони:
            # (0.06 × (1T × 0.2T) × (1.5m)^3) / (μ0 × 60ft) to lbf = 396 lbf
            # 2 × 1T × 1.5m / μ0 = 2.4MA
            # Повышая индукцию на +1 Тесла пони поднимается на +60 ft.
        # Масса магнитного кольца:
            # Плотность тока -- 1 MA/cm²
            # Плотность проводника (Graphitic carbon nitride) — 2.336 g/cm³
            # Масса кольца: circumference(1.5m) × 2.4cm² × 2.336g/cm³ = 5.3kg
        }

