metadict_detail['_++4 lvl (S) Изготовление (4 lvl Fabricate)'] = {
        # * !!! "Изготовление" (Fabricate) [Tra|-|-] — 120 футов, 10 минут каста, 30 кубометров дерева, или 3.4 кубометра камня/стали. Созданный объект должен умещаться в 20-футовый куб или в 8 соединённых 10-футовых кубов. Homebrew: убираем ограничение единственного объекта, увеличиваем объём воздействия, ставим ограничение по человеко-часам. Это заклинание позволяет изготовить за 10 минут то, с чем 100 чернорабочих или 10 ремесленников провозились бы 1 день (до 1000 рабочих часов). Этим заклинанием можно построить типичную избу-четырёхстенок 15×20 футов, за первый каст обработав 40 средних сосен, а за второй завершив все земляные и плотницкие работы, включая мебель и каменный очаг. Это заклинание можно использовать в рамках правил ремесла Книги игрока, создавая обычные волшебные вещи, вроде рун 1 круга. Этим заклинанием можно залатать полностью уничтоженный 10-футовый блок корабля, а затем с помощью надувных мешков или Control_Water поднять судно на воду. На больших уровнях +1000 нормо-часов/круг +50 бит/круг.
        # Физика заклинания:
        # Crafter_Domain вдвое хуже, но позволяет работать над разными задачами 8 часов.
        # Стоимость заклинания 4 круга -- 7 бит. Потенциальный доход -- 50-100 бит.
        # Зарплата мастера-ремесленника (20% семей) -- 1 бит/час.
        # Зарплата опытного ремесленника (30% семей) -- 0.5 бит/час
        #
        # Брусчатый дом (105 кв.метров жилых комнат) -- 30x30x20 футов
        # Работы в нормо-часах. Стройматериалы доставлены. Земляные работы сделаны Mold_Earth.
        # amber -sm брусчатый дом -S -E '$'
        # amber -sm брусчатый дом -S -E '='
        # _-$Строительство, каменщик (0.3_бит*нормо-час)......................... | 208
        # _-$Строительство, кровельщик (0.2_бит*нормо-час)....................... | 27
        # _-$Строительство, маляр (0.3_бит*нормо-час)............................ | 97
        # _-$Строительство, плотник (0.3_бит*нормо-час).......................... | 1,157
        # _-$Строительство, разнорабочий (0.2_бит*нормо-час)..................... | 62
        # _-$Строительство, разнорабочий-пегас (0.2_бит*нормо-час)............... | 67
        # _-$Строительство, штукатур (0.3_бит*нормо-час)......................... | 130
        # Всего 1748/4669 (38%) нормо-часов, 509/1233 (41%) суммарной стоимости.
        # Это 175 нормо-дней работы, 17.5 кастов. По объёму 18 заклинаний.
        }

