metadict_detail['_++7 lvl (S) Синостодвеомер (7 lvl Synostodweomer)'] = {
        # * +++ "Синостодвеомер Симбул" (Simbuls_Synostodweomer) [Tra|-|-] — касание, действием, час действия. Если цель тратит слот заклинания, цель может потратить равное кругу заклинания число костей хитов на лечение и добавить модификатор_характеристики заклинателя. Это лучше лечения на коротком отдыхе, ведь на 13 lvl вне боя и так найдётся кому мага подлатать.
        }

metadict_detail['_++7 lvl (S) Регенерация (7 lvl Regenerate)'] = {
        # * +++ "Регенерация" (Regenerate) [Tra|-|healing] — касание, минута каста, час действия. Мгновенно лечит 4d8+15 хитов, Постепенно лечит 1 hp/раунд, 10 hp/минуту. Потерянные части тела отрастают через 2 минуты. Бесконечные компоненты заклинаний из захваченных существ.
        }

metadict_detail['_++7 lvl (S) Воскрешение (7 lvl Resurrection)'] = {
        # * "Воскрешение" (Resurrection) [Nec|-|-] — 1000 бит (Rare бриллиант 5 карат), час каста. Оживляет погибшего менее столетия, если он не умер от старости и не был превращён в нежить. Заклинание исцеляет яды и немагические полезни, восстанавливает потерянные части тела. Цель получает штраф -4 к броскам атаки, спасброскам, проверкам характеристик, после продолжительного отдыха этот штраф уменьшается на единицу, пока не исчезнет. Если оживить существо, мёртвое больше года, заклинание изматывает, давая запрет на каст заклинаний, помеха на броски атаки, спасброски и проверки характеристик до продолжительного отдыха.
        }

metadict_detail['_++7 lvl (S) Изоляция (7 lvl Sequester)'] = {
        # * "Изоляция" (Sequester) [Tra|-|-] — 5000 бит, касание, действием, пока не рассеется. Согласное существо становится невидимым и необнаружимым магией. Время для него останавливается. Это заклинание может окончиться по условию, или по событию в радиусе 1 мили. Это заклинание оканчивается, если цель получает урон.
        # Способ спасти попавшего в беду агента -- Guiding_Tether + Sequester
        # _++7 lvl (S) Изоляция (7 lvl Sequester)................... | 1,132
        }

metadict_detail['_++7 lvl (S) Храм богов (7 lvl Temple_of_the_Gods)'] = {
        # * "Храм богов" (Temple_of_the_Gods) [Cnj|-|-] — час каста, 24 часа действия. Храм занимает куб 120×120 футов. Дверь храма могут открыть только избранные жрецом существа. Храм закрыт для магии прорицания. Небожителям, элементалям, феям, исчадиям, нежити нужно пройти спасбросок харизмы, чтобы войти в храм. Лечащие заклинания в храме восстанавливают +5 дополнительных хитов. Храм недоступен для планарных переходов. Храм нельзя развеять "Рассеиванием магии" (Dispel_Magic). Храм нельзя разрушить "Преградой антимагии" (Antimagic_Field). Заклинание "Распад" (Disintegrate) мгновенно уничтожает храм. Повторение "Храма богов" в течении года делает храм постоянным.
        }

metadict_detail['_++7 lvl (S) Узилище (7 lvl Forcecage)'] = {
        # * "Узилище" (Forcecage) [Tra|Cha|-] — 1500 бит, 100 футов, действием, час действия. 20-футовая клетка, или 10-футовый куб. Последний блокирует все заклинания изнутри и снаружи. Выход телепортом только после спасброска Харизмы. Заклинание "Рассеивание магии" (Dispel_Magic) не разрушает клетку.
        }

metadict_detail['_++7 lvl (S) Изменение тяготения (7 lvl Reverse_Gravity)'] = {
        # * !!! "Изменение тяготения" (Reverse_Gravity) [Tra|Dex|-] (C) — 100 футов, минута концентрации. 50-футовый радиус, высота 100 футов. Цели взлетают. Спасбросок ловкости, чтобы ухватиться, если есть за что. Полёт на 100 футов занимает две секунды. Homebrew: можно наложить на себя, тогда полёт по прямой со скоростью 600 футов и безопасное приземление до окончания заклинания.
        # Физика заклинания:
        # Падение ("Книга игрока" DnD 5e, стр 183):
            # sec | m/s  | ft  | ft/r | урон | dmg | Скорость отброса
            # --- | ---- | --- | ---- | ---- | --- | ----------------
            # 1/3 | 3.3  | 10  | 60   | 1d6  | 4   | Безопасно бойцу
            # 2/3 | 6.5  | 20  | 120  | 2d6  | 7   | Порог поражения
            # 1   | 9.8  | 30  | 180  | 3d6  | 11  | -
            # 2   | 19.6 | 100 | 400  | 10d6 | 35  | >50% потерь
            # 3   | 29.4 | 260 | 600  | 20d6 | 70  | 100% потерь
            # 9.8m/s² × (1/3) second to ft/round = 64 ft/round скорость
            # (9.8m × (3^2-1)) / (2-1) to ft = 257 ft падения за 3 секунды.
            # Максимум урона падения в DnD 5e, это 20d6 за 200 футов.
            # Максимум скорости падения, это 30 м/с, 600 ft/round.
        }

metadict_detail['_++7 lvl (S) Знак (7 lvl Symbol)'] = {
        # * "Знак" (Symbol) [Abj|choice|choice] — 1000 бит (Rare бриллиант 5 карат), минута каста. Постоянное. 60-футовый радиус поражения. Подобно заклинанию "Охранные руны" (Glyph_of_Warding), этот "Знак" нельзя сдвигать с места, он не может занимать более 10-футовой в диаметре зоны. Знак требует проверки интеллекта, чтобы обнаружить. 1) Знак "Смерти" — 10d10 некротического урона, спасбросок телосложения. 2) Знак "Разногласия" — спасбросок телосложения, ссора на минуту. 3) Знак "Страха" — спасбросок мудрости, цель бросает оружие и минуту бежит. 4) Знак "Безнадёжности" — спасбросок харизмы, цель не может атаковать. 5) Знак "Безумия" — спасбросок интеллекта, хаотичные движения, потеря контроля на минуту. 6) Знак "Боли" — спасбросок телосложения, недееспособность на 1 минуту. 7) Знак "Сна" — спасбросок мудрости, цели теряют сознание на 10 минут. 8) Знак "Ошеломления" — спасбросок мудрости, ошеломление на минуту.
        }

metadict_detail['_++7 lvl (S) Радужные брызги (7 lvl Prismatic_Spray)'] = {
        # * "Радужные брызги" (Prismatic_Spray) [Ilu|Dex|random] — 60 футов-конус, действием. Спасбросок ловкости, 1d8 выбор луча. Красный — огонь 10d6 урона, Оранжевый — кислота 10d6 урона, Жёлтый — молния 10d6, Зелёный — яд 10d6, Синий — холод 10d6. Индиго — опутывание и окаменение по правилам Flesh_to_Stone, спасброски Телосложения. Вельветовый — ослепление и изгнание на другой план, спасбросок Мудрости. d8 — удар двумя случайными лучами.
        }

metadict_detail['_++7 lvl (S) Слово силы: боль (7 lvl Power_Word_Pain)'] = {
        # * !!! "Слово силы: боль" (Power_Word_Pain) [Enc|Con|-] — 60 футов, действием, пока не рассеется. Замедляет скорость цели до 10 футов, даёт помеху на броски атаки и спасброски. Требует от цели броска Концентрации на каждое заклинание. Не срабатывает, если у цели больше 100 hp. Homebrew: спасбросок Телосложения действием, с помехой.
        }

metadict_detail['_++7 lvl (S) Божественное слово (7 lvl Divine_Word)'] = {
        # * "Божественное слово" (Divine_Word) [Enc|Cha|-] — бонусным действием. 30-футовый радиус. Спасбросок Харизмы. Меньше 50 hp — оглушены на минуту. Меньше 40 hp — оглушены и ослеплены на 10 минут. Меньше 30 hp — оглушены, ослеплены и ошеломлены на 1 час. Меньше 20 hp — убиты. Небожителей, элементалей, фей и исчадий, проваливших спасбросок, вне зависимости от их хитов, возвращает на родные планы. Они не могут вернуться 24 часа.
        }

metadict_detail['_++7 lvl (S) Палец смерти (7 lvl Finger_of_Death)'] = {
        # * "Палец смерти" (Finger_of_Death) [Nec|Con|necrotic] — 60 футов, действием. Спасбросок телосложения, 7d8+30 урона. Превращает убитого в зомби, навечно подчинённого колдуну.
        }

metadict_detail['_++7 lvl (S) Замедленный огненный шар (7 lvl Delayed_Blast_Fireball)'] = {
        # * "Замедленный огненный шар" (Delayed_Blast_Fireball) [Evo|Dex|fire] (C) — 150 футов, минута концентрации, 20-футовая сфера. Спасбросок ловкости. От 12d6 до 22d6 урона, каждый раунд задержки +1d6 урона. Взрывается по воле кастера, или при прерывании концентрации. Имеет форму светящегося шарика. Шарик можно отбросить на 40 футов или взять в руки при успешном спасброске Ловкости.
        }

metadict_detail['_++7 lvl (S) Огненный шторм (7 lvl Fire_Storm)'] = {
        # * "Огненный шторм" (Fire_Storm) [Evo|Dex|fire] — 150 футов, действием. Десять 10-футовых кубов, которые должны стоять вплотную. Спасбросок ловкости, 7d10 урона.
        }

metadict_detail['_++7 lvl (S) Смерч (7 lvl Whirlwind)'] = {
        # * "Смерч" (Whirlwind) [Evo|Dex|bludgeoning] (C) — 300 футов, действием, 10-футовый радиус, 10d6 урона, спасбросок Ловкости, минута концентрации. Можно действием переместить смерч на 30 футов/раунд. Смерч затягивает все средние и меньшие предметы. Спасбросок ловкости, или затягивает средних и меньших существ. Спасбросок силы, или существо опутано смерчом и подтягивается к его вершине.
        }

